[django/contrib/admin/utils.py] I think that's a good point! Thank you ☺️
For values like `"   test"`, `"test   "`, or `"  test  "`, where there are spaces on the left or right, the spaces should still be displayed.
It would be better to use quotes to clearly show the spaces in these values.
`“   test”`, `“test   ”`, `“  test  ”`

How about modifying the `display_for_value` as follows?
```
def convert_to_nbsp(value):
    blank = "\xa0"
    if not value.strip():
        value = value.replace(" ", blank)
    elif (value.startswith(" ") or value.endswith(" ")):
        value_length = len(value)
        left_space = value_length - len(value.lstrip())
        right_space = value_length - len(value.rstrip())
        left = blank * left_space
        right = blank * right_space
        value = left + value.strip() + right
    return value


def display_for_value(value, empty_value_display, boolean=False, avoid_quote=False):
    from django.contrib.admin.templatetags.admin_list import _boolean_icon

    if boolean:
        return _boolean_icon(value)
    elif value in EMPTY_VALUES:
        return empty_value_display
    elif isinstance(value, bool):
        return str(value)
    elif isinstance(value, datetime.datetime):
        return formats.localize(timezone.template_localtime(value))
    elif isinstance(value, (datetime.date, datetime.time)):
        return formats.localize(value)
    elif isinstance(value, (int, decimal.Decimal, float)):
        return formats.number_format(value)
    elif isinstance(value, (list, tuple)):
        return ", ".join(str(v) for v in value)
    elif isinstance(value, str):
        converted_value = convert_to_nbsp(value)
        if value != converted_value and not avoid_quote:
            return f"“{converted_value}”"
        return converted_value
    else:
        return str(value)

```

